@pytest.fixture
def actual(request, tmp_path):
    kind = getattr(request.node, 'callspec', None)
    task_kind = kind.params.get('task_kind', 'verified_source_leads') if kind is not None else 'verified_source_leads'
    with fixture(request.param, tmp_path / 'actual', task_kind) as value:
        yield value

